    def test_junos_acl_interfaces_parsed_single_input_output(self):
        parsed_str = """
            <rpc-reply message-id="urn:uuid:0cadb4e8-5bba-47f4-986e-72906227007f">
                <configuration>
                    <interfaces>
                        <interface>
                            <name>ge-1/0/0</name>
                            <unit>
                                <name>0</name>
                                <family>
                                    <inet>
                                        <filter>
                                            <input>
                                                <filter-name>in_acl</filter-name>
                                            </input>
                                            <output>
                                                <filter-name>out_acl</filter-name>
                                            </output>
                                        </filter>
                                    </inet>
                                </family>
                            </unit>
                        </interface>
                    </interfaces>
                </configuration>
            </rpc-reply>
        """

        set_module_args(dict(running_config=parsed_str, state="parsed"))
        result = self.execute_module(changed=False)

        parsed = result["parsed"][0]
        self.assertEqual(parsed["name"], "ge-1/0/0")
        self.assertEqual(parsed["access_groups"][0]["afi"], "ipv4")

        acls = parsed["access_groups"][0]["acls"]
        self.assertEqual(
            sorted(acls, key=lambda item: item["direction"]),
            [
                {"name": "in_acl", "direction": "in"},
                {"name": "out_acl", "direction": "out"},
            ],
        )

    def test_junos_acl_interfaces_parsed_missing_filter_name_skipped(self):
        parsed_str = """
            <rpc-reply message-id="urn:uuid:1cadb4e8-5bba-47f4-986e-72906227007f">
                <configuration>
                    <interfaces>
                        <interface>
                            <name>ge-1/0/1</name>
                            <unit>
                                <name>0</name>
                                <family>
                                    <inet>
                                        <filter>
                                            <input>
                                                <invalid-key>ignore-me</invalid-key>
                                            </input>
                                            <output>
                                                <filter-name>valid_out</filter-name>
                                            </output>
                                        </filter>
                                    </inet>
                                </family>
                            </unit>
                        </interface>
                    </interfaces>
                </configuration>
            </rpc-reply>
        """

        set_module_args(dict(running_config=parsed_str, state="parsed"))
        result = self.execute_module(changed=False)

        acls = result["parsed"][0]["access_groups"][0]["acls"]
        self.assertEqual(acls, [{"name": "valid_out", "direction": "out"}])
